(460, 1, '2025-07-31 22:11:42', '2025-08-01 01:11:42', '.ov-hd {\n	overflow:hidden;\n}\n/*\n * Post CSS: start\n */\n.ast-separate-container .ast-single-related-posts-container {\n	border-top:1px solid var(--ast-global-color-3);\n}\n\n.post-navigation {\n	display:none;\n}\n/*\n * Post CSS: end\n */\n\n.cnt-image {\n	display:block;\n	margin:0 auto!important;\n	width:150px!important;\n}\n\n.form-footer .wpcf7-response-output {\n	display:none;\n}\n\n/*\n * snippet_list_authors: start\n */\n.authors-list .items {\n	display:flex;\n	overflow-x: auto;\n	list-style:none;\n	gap:20px;\n	max-width:100%;\n	justify-content:center;\n}\n\n.authors-list li {\n	width:100px;\n	flex: 0 0 auto;\n}\n\n.ast-single-post .entry-content .authors-list a {\n	text-decoration:none;\n	text-align:center;\n}\n\n.authors-list img {\n	display:block;\n	width:150px;\n	border-radius:50%;\n	margin-bottom:20px;\n}\n\n.authors-list p {\n	margin-bottom:0;\n}\n/*\n * snippet_list_authors: end\n */\n\n/*\n * Author page: start\n */\n	body .pp-multiple-authors-layout-boxed ul li {\n		padding-top:0;\n		padding-bottom:0;\n	}\n\n.ppma-page-title.page-title {\n	text-indent:-100px;\n	overflow:hidden;\n}\n/*\n * Author page: end\n */\n\n.wp-block-latest-posts__featured-image {\n	position:relative;	\n}\n\n.wp-block-latest-posts__list .icon-player {\n	display:block;\n	border-radius:50%;\n	width:50px;\n	height:50px;\n	background-color:#fff;\n	position:absolute;\n	top:50%;\n	left:50%;\n	transform: translate(-50%, -50%);\n	background-color:rgba(255,255,255,0.4);\n}\n\n.wp-block-latest-posts__list .icon-player:before {\n	display:block;\n	content:\"\";\n  width: 0; \n  height: 0; \n  border-top: 10px solid transparent;\n  border-bottom: 10px solid transparent;\n  border-left: 15px solid var(--ast-global-color-5);\n	position:absolute;\n	top:50%;\n	left:50%;\n	transform:translate(-35%, -50%);\n}\n\n@media (min-width:768px) {\n		.ast-container #secondary .sidebar-main [id^=\"block\"].widget  {\n		padding:0 0 0 10px;\n	}\n	\n	.authors-list li {\n		width:150px;\n	}\n}\n\n@media (min-width:1024px) {\n	.cnt-image {\n		width:400px!important;\n	}	\n\n	/*\n	 * Author page: start\n	 */\n	body .pp-multiple-authors-layout-boxed ul li {\n		align-items:center;\n	}\n	.ppma-page-title.page-title {\n		text-indent:-120px;\n	}\n	/*\n	 * Author page: end\n	 */\n	\n	.wp-block-latest-posts__list .icon-player {\n		width:70px;\n		height:70px;\n	}\n\n	.wp-block-latest-posts__list .icon-player:before {\n		border-top: 20px solid transparent;\n		border-bottom: 20px solid transparent;\n		border-left: 30px solid var(--ast-global-color-5);\n	}\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '170-revision-v1', '', '', '2025-07-31 22:11:42', '2025-08-01 01:11:42', '', 170, 'https://alura.test/?p=460', 0, 'revision', '', 0),
